-- Incrementally copy the existing eight static course curricula into the new
-- Supabase course tables. Run after 20261031000000_course_management.sql.
-- This migration only inserts chapters/topics for a legacy course that has no
-- chapters yet. Existing chapter and topic records are never updated or deleted.
--
-- Before applying: take a Supabase backup and confirm all eight legacy course
-- mappings exist. If a course already has chapters, it is intentionally skipped.

do $migration$
declare
    course_data jsonb;
    chapter_data jsonb;
    topic_data jsonb;
    course_uuid uuid;
    chapter_uuid uuid;
    chapter_index integer;
    topic_index integer;
    curriculum_data constant jsonb := $seed$
[{"legacy_id":0,"chapters":[{"title_en":"HTML and page structure","title_ar":"HTML وبناء صفحات الويب","description_en":"Learn how browsers parse HTML into a document tree and why semantic elements communicate structure to browsers, assistive technology, and search engines. Build pages whose meaning remains clear even before visual styling is applied.\n\nStructure common content with headings, links, lists, images, and tables. Practice choosing each element for its meaning, writing useful alternative text, and making tabular information understandable.\n\nDesign forms as a sequence of labeled controls, suitable input types, and clear feedback. Connect browser validation to understandable instructions without treating client-side checks as a substitute for server validation.\n\nApply accessibility fundamentals such as keyboard operation, logical focus order, sufficient text alternatives, and headings that describe their sections. Validate structure with both automated checks and manual keyboard use.","description_ar":"تعرّف على كيفية تحويل المتصفح HTML إلى شجرة عناصر، ولماذا توضّح العناصر الدلالية بنية الصفحة للمتصفح وتقنيات المساعدة ومحركات البحث. ابنِ صفحات يظل معناها واضحًا حتى قبل إضافة التنسيق.\n\nنظّم المحتوى الشائع باستخدام العناوين والروابط والقوائم والصور والجداول. تدرب على اختيار العنصر وفق معناه، وكتابة نص بديل مفيد، وجعل البيانات الجدولية سهلة الفهم.\n\nصمّم النماذج كسلسلة من الحقول ذات التسميات وأنواع الإدخال المناسبة ورسائل التوضيح. استخدم تحقق المتصفح برسائل مفهومة، دون اعتباره بديلًا للتحقق على الخادم.\n\nطبّق أساسيات سهولة الوصول مثل التشغيل بلوحة المفاتيح وترتيب التركيز المنطقي والبدائل النصية الكافية والعناوين التي تصف أقسامها. افحص البنية آليًا ويدويًا بلوحة المفاتيح.","learning_objectives":{"en":["Choose semantic elements that match the purpose of each content region.","Organize headings and landmarks into a meaningful document outline.","Select the correct HTML element for content and navigation.","Describe informative images and provide clear table headers.","Associate every control with a visible, programmatic label.","Choose input types and constraints that help users submit valid data.","Identify common barriers in page structure and interaction.","Improve keyboard navigation and meaningful text alternatives."],"ar":["اختيار العناصر الدلالية المناسبة لغرض كل جزء من الصفحة.","تنظيم العناوين ومناطق الصفحة في بنية واضحة ومترابطة.","اختيار عنصر HTML الصحيح للمحتوى والتنقل.","وصف الصور المهمة وتحديد عناوين واضحة لأعمدة الجداول.","اربط كل حقل بتسمية ظاهرة ومقروءة برمجيًا.","اختيار أنواع الحقول والقيود التي تساعد المستخدم على إرسال بيانات صحيحة.","اكتشاف العوائق الشائعة في بنية الصفحات والتفاعل.","تحسين التنقل بلوحة المفاتيح والبدائل النصية ذات المعنى."]},"practical_applications":{"en":["Build a semantic article page and inspect its heading outline and landmarks.","Create a small product page containing a linked list, an informative image, and a comparison table.","Build a contact form with required fields, suitable input types, and useful error guidance.","Audit one page using only a keyboard and document three improvements."],"ar":["أنشئ صفحة مقال دلالية ثم راجع تسلسل عناوينها ومناطقها الرئيسية.","أنشئ صفحة منتج صغيرة تتضمن قائمة مرتبطة وصورة موضحة وجدول مقارنة.","أنشئ نموذج تواصل بحقول مطلوبة وأنواع إدخال مناسبة وإرشادات واضحة عند الخطأ.","افحص صفحة باستخدام لوحة المفاتيح فقط وسجّل ثلاثة تحسينات مطلوبة."]},"real_world_examples":{"en":[],"ar":[]},"tools_and_technologies":{"en":[],"ar":[]},"exercises":{"en":["Build a semantic article page and inspect its heading outline and landmarks.","Create a small product page containing a linked list, an informative image, and a comparison table.","Build a contact form with required fields, suitable input types, and useful error guidance.","Audit one page using only a keyboard and document three improvements."],"ar":["أنشئ صفحة مقال دلالية ثم راجع تسلسل عناوينها ومناطقها الرئيسية.","أنشئ صفحة منتج صغيرة تتضمن قائمة مرتبطة وصورة موضحة وجدول مقارنة.","أنشئ نموذج تواصل بحقول مطلوبة وأنواع إدخال مناسبة وإرشادات واضحة عند الخطأ.","افحص صفحة باستخدام لوحة المفاتيح فقط وسجّل ثلاثة تحسينات مطلوبة."]},"expected_outcomes":{"en":["Choose semantic elements that match the purpose of each content region.","Organize headings and landmarks into a meaningful document outline.","Select the correct HTML element for content and navigation.","Describe informative images and provide clear table headers.","Associate every control with a visible, programmatic label.","Choose input types and constraints that help users submit valid data.","Identify common barriers in page structure and interaction.","Improve keyboard navigation and meaningful text alternatives."],"ar":["اختيار العناصر الدلالية المناسبة لغرض كل جزء من الصفحة.","تنظيم العناوين ومناطق الصفحة في بنية واضحة ومترابطة.","اختيار عنصر HTML الصحيح للمحتوى والتنقل.","وصف الصور المهمة وتحديد عناوين واضحة لأعمدة الجداول.","اربط كل حقل بتسمية ظاهرة ومقروءة برمجيًا.","اختيار أنواع الحقول والقيود التي تساعد المستخدم على إرسال بيانات صحيحة.","اكتشاف العوائق الشائعة في بنية الصفحات والتفاعل.","تحسين التنقل بلوحة المفاتيح والبدائل النصية ذات المعنى."]},"topics":[{"title_en":"HTML document structure and semantic elements","title_ar":"هيكل مستند HTML والعناصر الدلالية","short_description_en":"Understand HTML document structure and semantic elements and its role in HTML and page structure.","short_description_ar":"افهم هيكل مستند HTML والعناصر الدلالية ودوره ضمن HTML وبناء صفحات الويب.","detailed_content_en":"HTML document structure and semantic elements is a building block of HTML and page structure. Learn how browsers parse HTML into a document tree and why semantic elements communicate structure to browsers, assistive technology, and search engines. Build pages whose meaning remains clear even before visual styling is applied.\n\nStructure common content with headings, links, lists, images, and tables. Practice choosing each element for its meaning, writing useful alternative text, and making tabular information understandable.\n\nDesign forms as a sequence of labeled controls, suitable input types, and clear feedback. Connect browser validation to understandable instructions without treating client-side checks as a substitute for server validation.\n\nApply accessibility fundamentals such as keyboard operation, logical focus order, sufficient text alternatives, and headings that describe their sections. Validate structure with both automated checks and manual keyboard use.\n\nTo understand it, identify its purpose, required inputs or conditions, the rule it follows, and the result it produces. Relate each part to the other topics in this chapter instead of treating the term as an isolated definition.\n\nApply the concept to a small example, then change one input or condition and predict how the result changes. Check the prediction and explain any difference.","detailed_content_ar":"هيكل مستند HTML والعناصر الدلالية من اللبنات الأساسية في HTML وبناء صفحات الويب. تعرّف على كيفية تحويل المتصفح HTML إلى شجرة عناصر، ولماذا توضّح العناصر الدلالية بنية الصفحة للمتصفح وتقنيات المساعدة ومحركات البحث. ابنِ صفحات يظل معناها واضحًا حتى قبل إضافة التنسيق.\n\nنظّم المحتوى الشائع باستخدام العناوين والروابط والقوائم والصور والجداول. تدرب على اختيار العنصر وفق معناه، وكتابة نص بديل مفيد، وجعل البيانات الجدولية سهلة الفهم.\n\nصمّم النماذج كسلسلة من الحقول ذات التسميات وأنواع الإدخال المناسبة ورسائل التوضيح. استخدم تحقق المتصفح برسائل مفهومة، دون اعتباره بديلًا للتحقق على الخادم.\n\nطبّق أساسيات سهولة الوصول مثل التشغيل بلوحة المفاتيح وترتيب التركيز المنطقي والبدائل النصية الكافية والعناوين التي تصف أقسامها. افحص البنية آليًا ويدويًا بلوحة المفاتيح.\n\nلفهمه، حدّد الغرض منه ومدخلاته أو شروطه والقاعدة التي يتبعها والنتيجة التي ينتجها. اربط كل جزء بباقي موضوعات الفصل بدل التعامل معه كتعريف منفصل.\n\nطبّق الفكرة على مثال صغير، ثم غيّر مدخلًا أو شرطًا واحدًا وتوقّع أثر ذلك. اختبر توقعك واشرح أي اختلاف.","step_by_step":{"en":["State what HTML document structure and semantic elements is used for and when it is appropriate.","List its inputs, rules, constraints, and expected output.","Work through a normal example and verify each intermediate step.","Try a boundary or failure case and explain the result."],"ar":["وضّح وظيفة هيكل مستند HTML والعناصر الدلالية ومتى يكون استخدامه مناسبًا.","اكتب مدخلاته وقواعده وقيوده والنتيجة المتوقعة.","حلّل مثالًا عاديًا وتحقق من كل خطوة وسيطة.","جرّب حالة حدية أو حالة فشل واشرح النتيجة."]},"practical_examples":{"en":["Build a small example that applies HTML document structure and semantic elements to a realistic task from HTML and page structure."],"ar":["أنشئ مثالًا صغيرًا يطبّق هيكل مستند HTML والعناصر الدلالية في مهمة واقعية مرتبطة بـHTML وبناء صفحات الويب."]},"use_cases":{"en":["Use HTML document structure and semantic elements when a solution needs the behavior or outcome taught in HTML and page structure."],"ar":["استخدم هيكل مستند HTML والعناصر الدلالية عندما يحتاج الحل إلى السلوك أو النتيجة التي يشرحها HTML وبناء صفحات الويب."]},"common_mistakes":{"en":["Applying the concept without checking its inputs, assumptions, or constraints.","Testing only one normal example and overlooking boundary cases."],"ar":["تطبيق المفهوم دون فحص المدخلات أو الافتراضات أو القيود.","اختبار مثال عادي واحد وتجاهل الحالات الحدية."]},"exercises":{"en":["Explain HTML document structure and semantic elements in your own words and draw or write the steps it follows.","Create a second example with different inputs, predict the result, then verify and justify it."],"ar":["اشرح هيكل مستند HTML والعناصر الدلالية بأسلوبك وارسم أو اكتب الخطوات التي يتبعها.","أنشئ مثالًا ثانيًا بمدخلات مختلفة، وتوقّع النتيجة ثم تحقق منها وبرّرها."]}},{"title_en":"Headings, links, lists, images, and tables","title_ar":"العناوين والروابط والقوائم والصور والجداول","short_description_en":"Understand Headings, links, lists, images, and tables and its role in HTML and page structure.","short_description_ar":"افهم العناوين والروابط والقوائم والصور والجداول ودوره ضمن HTML