$seed$::jsonb;
begin
    perform pg_advisory_xact_lock(hashtext('techsphere_legacy_course_curriculum_v1'));

    for course_data in
        select value from jsonb_array_elements(curriculum_data)
    loop
        select id into course_uuid
        from public.courses
        where legacy_id = (course_data ->> 'legacy_id')::integer;

        if course_uuid is null then
            raise exception 'Missing seeded course mapping for legacy course %.',
                course_data ->> 'legacy_id';
        end if;

        if exists (
            select 1 from public.course_chapters
            where course_id = course_uuid
        ) then
            raise notice 'Skipping legacy course % because chapters already exist.',
                course_data ->> 'legacy_id';
            continue;
        end if;

        chapter_index := 0;
        for chapter_data in
            select value from jsonb_array_elements(course_data -> 'chapters')
        loop
            insert into public.course_chapters (
                course_id,
                title_en,
                title_ar,
                description_en,
                description_ar,
                learning_objectives,
                practical_applications,
                real_world_examples,
                tools_and_technologies,
                exercises,
                expected_outcomes,
                sort_order
            )
            values (
                course_uuid,
                chapter_data ->> 'title_en',
                chapter_data ->> 'title_ar',
                coalesce(chapter_data ->> 'description_en', ''),
                coalesce(chapter_data ->> 'description_ar', ''),
                coalesce(chapter_data -> 'learning_objectives', '{"en":[],"ar":[]}'::jsonb),
                coalesce(chapter_data -> 'practical_applications', '{"en":[],"ar":[]}'::jsonb),
                coalesce(chapter_data -> 'real_world_examples', '{"en":[],"ar":[]}'::jsonb),
                coalesce(chapter_data -> 'tools_and_technologies', '{"en":[],"ar":[]}'::jsonb),
                coalesce(chapter_data -> 'exercises', '{"en":[],"ar":[]}'::jsonb),
                coalesce(chapter_data -> 'expected_outcomes', '{"en":[],"ar":[]}'::jsonb),
                chapter_index
            )
            returning id into chapter_uuid;

            topic_index := 0;
            for topic_data in
                select value from jsonb_array_elements(chapter_data -> 'topics')
            loop
                insert into public.chapter_topics (
                    chapter_id,
                    title_en,
                    title_ar,
                    short_description_en,
                    short_description_ar,
                    detailed_content_en,
                    detailed_content_ar,
                    step_by_step,
                    practical_examples,
                    use_cases,
                    common_mistakes,
                    exercises,
                    sort_order
                )
                values (
                    chapter_uuid,
                    topic_data ->> 'title_en',
                    topic_data ->> 'title_ar',
                    coalesce(topic_data ->> 'short_description_en', ''),
                    coalesce(topic_data ->> 'short_description_ar', ''),
                    coalesce(topic_data ->> 'detailed_content_en', ''),
                    coalesce(topic_data ->> 'detailed_content_ar', ''),
                    coalesce(topic_data -> 'step_by_step', '{"en":[],"ar":[]}'::jsonb),
                    coalesce(topic_data -> 'practical_examples', '{"en":[],"ar":[]}'::jsonb),
                    coalesce(topic_data -> 'use_cases', '{"en":[],"ar":[]}'::jsonb),
                    coalesce(topic_data -> 'common_mistakes', '{"en":[],"ar":[]}'::jsonb),
                    coalesce(topic_data -> 'exercises', '{"en":[],"ar":[]}'::jsonb),
                    topic_index
                );
                topic_index := topic_index + 1;
            end loop;
            chapter_index := chapter_index + 1;
        end loop;
    end loop;
end;
$migration$;
